      }

      // Trying to hit the tags endpoint to verify connection
      // Note: Cloud providers might not expose /api/tags, but standard Ollama does. 
      // If using cloud, might need to try a simple generate.
      const res = await fetch(`${aiSettings.ollamaUrl}/api/tags`, {
