    const diff = currentWinRate - expectedWinRate;
    if (diff < -0.3) change += 20;
    else if (diff < -0.1) change += 10;
    else if (diff > 0.2) change -= 15;
    else if (diff > 0) change -= 5;
    if (team.stats.losses > team.stats.wins) change += 5;
    return change;
  };

