               {aiErrorDetails && (
                  <div className={`p-4 rounded-xl border ${aiConnectionStatus === 'OFFLINE' ? 'bg-yellow-500/10 border-yellow-500/50' : 'bg-red-500/10 border-red-500/50'}`}>
