                       <span className={`${aiConnectionStatus === 'OFFLINE' ? 'text-yellow-400' : 'text-red-400'} font-bold text-xs uppercase`}>
                         {aiConnectionStatus === 'OFFLINE' ? 'Offline Mode Active' : 'Connection Error'}
                       </span>
