const shuffle = <T>(array: T[]): T[] => {
    let currentIndex = array.length,  randomIndex;
    while (currentIndex != 0) {
      randomIndex = Math.floor(Math.random() * currentIndex);
      currentIndex--;
      [array[currentIndex], array[randomIndex]] = [
        array[randomIndex], array[currentIndex]];
    }
    return array;
};

export const fetchRealTeamLogos = async (): Promise<Record<string, string>> => {
  try {
    const response = await fetch('https://site.api.espn.com/apis/site/v2/sports/football/college-football/teams?limit=1000&groups=80');
    const data = await response.json();
    const map: Record<string, string> = {};

    if (data?.sports?.[0]?.leagues?.[0]?.teams) {
      data.sports[0].leagues[0].teams.forEach((t: any) => {
        const team = t.team;
        if (team.logos?.[0]?.href) {
          const href = team.logos[0].href;
          map[team.displayName] = href;
          map[team.shortDisplayName] = href;
          map[team.name] = href;
          map[team.abbreviation] = href;
          map[team.name.replace(' State', ' St')] = href;
        }
      });
    }
    return map;
  } catch (err) {
    console.error("Error fetching logos:", err);
    return {};
  }
};

// Map ESPN API group names to our internal Conference types
const CONF_NAME_MAP: Record<string, string> = {
    'American Athletic Conference': 'AAC',
    'Atlantic Coast Conference': 'ACC',
    'Big 12 Conference': 'Big 12',
    'Big Ten Conference': 'Big Ten',
    'Conference USA': 'CUSA',
    'FBS Independents': 'Independent',
    'Mid-American Conference': 'MAC',
    'Mountain West Conference': 'Mountain West',
    'Pac-12 Conference': 'Pac-12',
    'Southeastern Conference': 'SEC',
    'Sun Belt Conference': 'Sun Belt'
};

// Fetches conference logos using the data source from cfbplotR (sportsdataverse)
export const fetchConferenceLogos = async (): Promise<Record<string, string>> => {
  try {
     // First try ESPN API for groups to get IDs, then construct URLs which is very reliable
     const res = await fetch('https://site.api.espn.com/apis/site/v2/sports/football/college-football/groups');
     const data = await res.json();
     const map: Record<string, string> = {};

     if (data.groups) {
        data.groups.forEach((g: any) => {
           // Standard ESPN CDN path for conference logos
           const logoUrl = `https://a.espncdn.com/i/teamlogos/ncaa/conf/500/${g.id}.png`;

           // Map standard names
           map[g.name] = logoUrl;
           map[g.shortName] = logoUrl;

           // Map using our internal dictionary to ensure keys match 'Conference' type
           if (CONF_NAME_MAP[g.name]) {
               map[CONF_NAME_MAP[g.name]] = logoUrl;
           }
        });
     }
     return map;
  } catch (e) {
     console.error("Error fetching conference logos", e);
     // Fallback to manual map if API fails using verified IDs
     return {
        'SEC': 'https://a.espncdn.com/i/teamlogos/ncaa/conf/500/8.png',
        'ACC': 'https://a.espncdn.com/i/teamlogos/ncaa/conf/500/1.png',
        'Big 12': 'https://a.espncdn.com/i/teamlogos/ncaa/conf/500/4.png',
        'Big Ten': 'https://a.espncdn.com/i/teamlogos/ncaa/conf/500/5.png',
        'Pac-12': 'https://a.espncdn.com/i/teamlogos/ncaa/conf/500/9.png',
        'CUSA': 'https://a.espncdn.com/i/teamlogos/ncaa/conf/500/12.png',
